query GetDetailedSystemMetrics($timeRange: String, $includeHistory: Boolean) {
  systemMetrics(timeRange: $timeRange, includeHistory: $includeHistory) {
    timestamp
    cpu {
      usage
      loadAverage
      cores
    }
    memory {
      used
      total
      percentage
      available
    }
    database {
      connections {
        active
        idle
        total
      }
      performance {
        queriesPerSecond
        avgQueryTime
        slowQueries
      }
    }
    history {
      timestamp
      cpuUsage
      memoryUsage
    }
  }
}
